def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check if start or goal is a wall or out of bounds
    if not (0 <= start[0] < rows and 0 <= start[1] < cols) or grid[start[0]][start[1]] == '#':
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols) or grid[goal[0]][goal[1]] == '#':
        return []

    # If start and goal are the same and it's a free cell
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    # Initialize distance matrix with infinity
    dist = [[float('inf')] * cols for _ in range(rows)]
    dist[start[0]][start[1]] = 0

    # Bellman-Ford style sweep relaxation
    for i in range(rows * cols):
        updated = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == '#':
                    continue
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                        if dist[nr][nc] > dist[r][c] + 1:
                            dist[nr][nc] = dist[r][c] + 1
                            updated = True
        if not updated:
            break

    # Reconstruct path
    if dist[goal[0]][goal[1]] == float('inf'):
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        # Find the previous cell with distance one less
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = current[0] + dr, current[1] + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and dist[nr][nc] == dist[current[0]][current[1]] - 1:
                current = (nr, nc)
                break
    path.append(start)
    return path[::-1]

